BEGIN TRANSACTION;
CREATE TABLE alerts_sent (
	id INTEGER NOT NULL, 
	listing_id VARCHAR NOT NULL, 
	alert_type VARCHAR, 
	sent_at DATETIME, 
	message_preview TEXT, 
	chat_message_id INTEGER, 
	PRIMARY KEY (id)
);
CREATE TABLE feedback (
	id INTEGER NOT NULL, 
	listing_id VARCHAR NOT NULL, 
	verdict VARCHAR NOT NULL, 
	note TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE investment_metrics (
	listing_id VARCHAR NOT NULL, 
	gross_yield_pct FLOAT, 
	net_yield_pct FLOAT, 
	roi_pct FLOAT, 
	payback_years FLOAT, 
	estimated_monthly_rent FLOAT, 
	total_investment FLOAT, 
	investment_score FLOAT, 
	score_breakdown JSON, 
	computed_at DATETIME, 
	PRIMARY KEY (listing_id)
);
CREATE TABLE listings (
	id VARCHAR NOT NULL, 
	portal VARCHAR NOT NULL, 
	external_id VARCHAR NOT NULL, 
	url VARCHAR NOT NULL, 
	title TEXT, 
	price FLOAT, 
	area_m2 FLOAT, 
	price_per_m2 FLOAT, 
	rooms INTEGER, 
	bathrooms INTEGER, 
	floor VARCHAR, 
	condition VARCHAR, 
	latitude FLOAT, 
	longitude FLOAT, 
	district VARCHAR, 
	city VARCHAR, 
	zip_code VARCHAR, 
	description TEXT, 
	photo_urls JSON, 
	raw_html_hash VARCHAR, 
	price_history JSON, 
	first_seen_at DATETIME, 
	last_seen_at DATETIME, 
	is_active BOOLEAN, 
	PRIMARY KEY (id)
);
CREATE TABLE rent_zone_averages (
	id INTEGER NOT NULL, 
	district VARCHAR, 
	city VARCHAR NOT NULL, 
	avg_rent_per_m2 FLOAT NOT NULL, 
	sample_size INTEGER, 
	updated_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE telegram_state (
	"key" VARCHAR NOT NULL, 
	value VARCHAR NOT NULL, 
	updated_at DATETIME, 
	PRIMARY KEY ("key")
);
COMMIT;
